     1	import sortBy from 'lodash/sortBy';
     2	import React, {useContext, useRef} from 'react';
     3	import {View} from 'react-native';
     4	import type {OnyxEntry} from 'react-native-onyx';
     5	import type {Emoji} from '@assets/emojis/types';
     6	import OfflineWithFeedback from '@components/OfflineWithFeedback';
     7	import Tooltip from '@components/Tooltip/PopoverAnchorTooltip';
     8	import withCurrentUserPersonalDetails from '@components/withCurrentUserPersonalDetails';
     9	import type {WithCurrentUserPersonalDetailsProps} from '@components/withCurrentUserPersonalDetails';
    10	import useThemeStyles from '@hooks/useThemeStyles';
    11	import * as EmojiUtils from '@libs/EmojiUtils';
    12	import {ReactionListContext} from '@pages/home/ReportScreenContext';
    13	import type {ReactionListAnchor, ReactionListEvent} from '@pages/home/ReportScreenContext';
    14	import CONST from '@src/CONST';
    15	import type {Locale, ReportAction, ReportActionReactions} from '@src/types/onyx';
    16	import type {PendingAction} from '@src/types/onyx/OnyxCommon';
    17	import AddReactionBubble from './AddReactionBubble';
    18	import EmojiReactionBubble from './EmojiReactionBubble';
    19	import ReactionTooltipContent from './ReactionTooltipContent';
    20	
    21	type ReportActionItemEmojiReactionsProps = WithCurrentUserPersonalDetailsProps & {
    22	    /** All the emoji reactions for the report action. */
    23	    emojiReactions: OnyxEntry<ReportActionReactions>;
    24	
    25	    /** The user's preferred locale. */
    26	    preferredLocale?: OnyxEntry<Locale>;
    27	
    28	    /** The report action that these reactions are for */
    29	    reportAction: ReportAction;
    30	
    31	    /**
    32	     * Function to call when the user presses on an emoji.
    33	     * This can also be an emoji the user already reacted with,
    34	     * hence this function asks to toggle the reaction by emoji.
    35	     */
    36	    toggleReaction: (emoji: Emoji, ignoreSkinToneOnCompare?: boolean) => void;
    37	
    38	    /** We disable reacting with emojis on report actions that have errors */
    39	    shouldBlockReactions?: boolean;
    40	
    41	    /** Function to update emoji picker state */
    42	    setIsEmojiPickerActive?: (state: boolean) => void;
    43	};
    44	
    45	type PopoverReactionListAnchors = Record<string, ReactionListAnchor>;
    46	
    47	type FormattedReaction = {
    48	    /** The emoji codes to display in the bubble */
    49	    emojiCodes: string[];
    50	
    51	    /** IDs of users used the reaction */
    52	    userAccountIDs: number[];
    53	
    54	    /** Total reaction count */
    55	    reactionCount: number;
    56	
    57	    /** Whether the current account has reacted to the report action */
    58	    hasUserReacted: boolean;
    59	
    60	    /** Oldest timestamp of when the emoji was added */
    61	    oldestTimestamp: string;
    62	
    63	    /** Callback to fire on press */
    64	    onPress: () => void;
    65	
    66	    /** Callback to fire on reaction list open */
    67	    onReactionListOpen: (event: ReactionListEvent) => void;
    68	
    69	    /** The name of the emoji */
    70	    reactionEmojiName: string;
    71	
    72	    /** The type of action that's pending  */
    73	    pendingAction?: PendingAction;
    74	
    75	    setIsEmojiPickerActive?: (state: boolean) => void;
    76	};
    77	
    78	function ReportActionItemEmojiReactions({
    79	    reportAction,
    80	    currentUserPersonalDetails,
    81	    toggleReaction,
    82	    emojiReactions = {},
    83	    shouldBlockReactions = false,
    84	    preferredLocale = CONST.LOCALES.DEFAULT,
    85	    setIsEmojiPickerActive,
    86	}: ReportActionItemEmojiReactionsProps) {
    87	    const styles = useThemeStyles();
    88	    const reactionListRef = useContext(ReactionListContext);
    89	    const popoverReactionListAnchors = useRef<PopoverReactionListAnchors>({});
    90	
    91	    let totalReactionCount = 0;
    92	
    93	    const reportActionID = reportAction.reportActionID;
    94	
    95	    // Each emoji is sorted by the oldest timestamp of user reactions so that they will always appear in the same order for everyone
    96	    const formattedReactions: Array<FormattedReaction | null> = sortBy(
    97	        Object.entries(emojiReactions ?? {}).map(([emojiName, emojiReaction]) => {
    98	            const {emoji, emojiCodes, reactionCount, hasUserReacted, userAccountIDs, oldestTimestamp} = EmojiUtils.getEmojiReactionDetails(
    99	                emojiName,
   100	                emojiReaction,
   101	                currentUserPersonalDetails.accountID,
   102	            );
   103	
   104	            if (reactionCount === 0) {
   105	                return null;
   106	            }
   107	            totalReactionCount += reactionCount;
   108	
   109	            const onPress = () => {
   110	                toggleReaction(emoji, true);
   111	            };
   112	
   113	            const onReactionListOpen = (event: ReactionListEvent) => {
   114	                reactionListRef?.current?.showReactionList(event, popoverReactionListAnchors.current[emojiName], emojiName, reportActionID);
   115	            };
   116	
   117	            return {
   118	                emojiCodes,
   119	                userAccountIDs,
   120	                reactionCount,
   121	                hasUserReacted,
   122	                oldestTimestamp,
   123	                onPress,
   124	                onReactionListOpen,
   125	                reactionEmojiName: emojiName,
   126	            };
   127	        }),
   128	        ['oldestTimestamp'],
   129	    );
   130	
   131	    return (
   132	        totalReactionCount > 0 && (
   133	            <View style={[styles.flexRow, styles.flexWrap, styles.gap1, styles.mt2]}>
   134	                {formattedReactions.map((reaction) => {
   135	                    if (reaction === null) {
   136	                        return;
   137	                    }
   138	                    return (
   139	                        <Tooltip
   140	                            renderTooltipContent={() => (
   141	                                <ReactionTooltipContent
   142	                                    emojiName={EmojiUtils.getLocalizedEmojiName(reaction.reactionEmojiName, preferredLocale)}
   143	                                    emojiCodes={reaction.emojiCodes}
   144	                                    accountIDs={reaction.userAccountIDs}
   145	                                    currentUserPersonalDetails={currentUserPersonalDetails}
   146	                                />
   147	                            )}
   148	                            renderTooltipContentKey={[...reaction.userAccountIDs.map(String), ...reaction.emojiCodes]}
   149	                            key={reaction.reactionEmojiName}
   150	                        >
   151	                            <View>
   152	                                <EmojiReactionBubble
   153	                                    ref={(ref) => (popoverReactionListAnchors.current[reaction.reactionEmojiName] = ref ?? null)}
   154	                                    count={reaction.reactionCount}
   155	                                    emojiCodes={reaction.emojiCodes}
   156	                                    onPress={reaction.onPress}
   157	                                    hasUserReacted={reaction.hasUserReacted}
   158	                                    onReactionListOpen={reaction.onReactionListOpen}
   159	                                    shouldBlockReactions={shouldBlockReactions}
   160	                                />
   161	                            </View>
   162	                        </Tooltip>
   163	                    );
   164	                })}
   165	                {!shouldBlockReactions && (
   166	                    <AddReactionBubble
   167	                        onSelectEmoji={toggleReaction}
   168	                        reportAction={reportAction}
   169	                        setIsEmojiPickerActive={setIsEmojiPickerActive}
   170	                    />
   171	                )}
   172	            </View>
   173	        )
   174	    );
   175	}
   176	
   177	ReportActionItemEmojiReactions.displayName = 'ReportActionItemReactions';
   178	
   179	export default withCurrentUserPersonalDetails(ReportActionItemEmojiReactions);
